=== FILE: apb_regs.v ===
`timescale 1ns/1ps
`default_nettype none
// apb_regs: four 32-bit read/write registers behind an APB4 subordinate port.
// Implements microarchitecture.md (approved) for interface_spec.md (approved).
// Zero wait states, no state machine; the only state is reg0..reg3.
module apb_regs #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);
    localparam STRB_WIDTH = DATA_WIDTH / 8;

    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    // Access phase: the one cycle in which the response is sampled and a
    // write takes effect.
    wire access = psel && penable;

    // is_mapped: word aligned and inside 0x0..0xC (addr >> 4 == 0).
    wire mapped = (paddr[1:0] == 2'b00) &&
                  (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});

    wire [1:0] idx = paddr[3:2];
    wire       wr  = access && pwrite && mapped;

    // Byte mask from pstrb: merge(old, data, strb) = (old & ~m) | (data & m).
    wire [DATA_WIDTH-1:0] wmask;
    genvar b;
    generate
        for (b = 0; b < STRB_WIDTH; b = b + 1) begin : g_wmask
            assign wmask[8*b +: 8] = {8{pstrb[b]}};
        end
    endgenerate

    // Register file, synchronous active-low reset.
    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else if (wr) begin
            if (idx == 2'd0) reg0 <= (reg0 & ~wmask) | (pwdata & wmask);
            if (idx == 2'd1) reg1 <= (reg1 & ~wmask) | (pwdata & wmask);
            if (idx == 2'd2) reg2 <= (reg2 & ~wmask) | (pwdata & wmask);
            if (idx == 2'd3) reg3 <= (reg3 & ~wmask) | (pwdata & wmask);
        end
    end

    // Read multiplexer.
    reg [DATA_WIDTH-1:0] rd_mux;
    always @(*) begin
        case (idx)
            2'd0:    rd_mux = reg0;
            2'd1:    rd_mux = reg1;
            2'd2:    rd_mux = reg2;
            default: rd_mux = reg3;
        endcase
    end

    assign prdata  = (access && !pwrite && mapped) ? rd_mux : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = access && !mapped;

`ifdef FORMAL
    // ---------------------------------------------------------------
    // Design-intent properties. Decode and merge are written
    // independently of `mapped` and `wmask` above.
    // ---------------------------------------------------------------
    reg f_past_valid = 1'b0;
    always @(posedge pclk) f_past_valid <= 1'b1;

    wire f_access = psel && penable;
    wire f_mapped = (paddr == 8'h00) || (paddr == 8'h04) ||
                    (paddr == 8'h08) || (paddr == 8'h0C);
    wire f_wr     = f_access && pwrite && f_mapped;

    // Manager assumptions (APB4 rules).
    always @(*) begin
        if (!f_past_valid) assume(!presetn);
        if (!presetn)      assume(!psel);
        if (penable)       assume(psel);
    end

    always @(posedge pclk) begin
        if (f_past_valid) begin
            // Setup is always followed by access (pready is high).
            if ($past(presetn && psel && !penable) && presetn)
                assume(psel && penable);
            // penable only after a setup phase.
            if (penable)
                assume($past(psel && !penable));
            // Request stable from setup through access.
            if (psel && penable) begin
                assume(paddr  == $past(paddr));
                assume(pwrite == $past(pwrite));
                assume(pwdata == $past(pwdata));
                assume(pstrb  == $past(pstrb));
            end
        end
    end

    // Response properties.
    always @(*) begin
        assert(pready);
        if (!f_access) begin
            assert(prdata == {DATA_WIDTH{1'b0}});
            assert(!pslverr);
        end else begin
            assert(pslverr == !f_mapped);
            if (pwrite || !f_mapped)
                assert(prdata == {DATA_WIDTH{1'b0}});
            else if (paddr == 8'h00) assert(prdata == reg0);
            else if (paddr == 8'h04) assert(prdata == reg1);
            else if (paddr == 8'h08) assert(prdata == reg2);
            else                     assert(prdata == reg3);
        end
    end

    // Registers are zero after reset.
    always @(posedge pclk) begin
        if (f_past_valid && !$past(presetn)) begin
            assert(reg0 == {DATA_WIDTH{1'b0}});
            assert(reg1 == {DATA_WIDTH{1'b0}});
            assert(reg2 == {DATA_WIDTH{1'b0}});
            assert(reg3 == {DATA_WIDTH{1'b0}});
        end
    end

    // Each byte changes only in a mapped write to its register with its
    // strobe set, and then to the written byte.
    genvar fb;
    generate
        for (fb = 0; fb < STRB_WIDTH; fb = fb + 1) begin : g_fbyte
            always @(posedge pclk) begin
                if (f_past_valid && $past(presetn)) begin
                    if ($past(f_wr && paddr[3:2] == 2'd0 && pstrb[fb]))
                        assert(reg0[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg0[8*fb +: 8] == $past(reg0[8*fb +: 8]));
                    if ($past(f_wr && paddr[3:2] == 2'd1 && pstrb[fb]))
                        assert(reg1[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg1[8*fb +: 8] == $past(reg1[8*fb +: 8]));
                    if ($past(f_wr && paddr[3:2] == 2'd2 && pstrb[fb]))
                        assert(reg2[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg2[8*fb +: 8] == $past(reg2[8*fb +: 8]));
                    if ($past(f_wr && paddr[3:2] == 2'd3 && pstrb[fb]))
                        assert(reg3[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg3[8*fb +: 8] == $past(reg3[8*fb +: 8]));
                end
            end
        end
    endgenerate
`endif

endmodule
`default_nettype wire
=== END FILE ===
