`timescale 1ns/1ps
`default_nettype none
// Self-checking directed testbench for apb_regs.
// Drives inputs after the falling edge, samples 1 ns later (well before the
// rising edge). Every failed check is reported with $error.
module apb_regs_tb;
    reg         pclk    = 1'b0;
    reg         presetn = 1'b0;
    reg  [7:0]  paddr   = 8'h00;
    reg         psel    = 1'b0;
    reg         penable = 1'b0;
    reg         pwrite  = 1'b0;
    reg  [31:0] pwdata  = 32'h0;
    reg  [3:0]  pstrb   = 4'h0;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    integer passed = 0;
    integer failed = 0;
    reg [8*64-1:0] nonce;

    apb_regs #(.ADDR_WIDTH(8), .DATA_WIDTH(32)) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    always #5 pclk = ~pclk;

    task check_bit(input got, input exp, input [8*48-1:0] what);
    begin
        if (got === exp) passed = passed + 1;
        else begin
            failed = failed + 1;
            $error("FAIL %0s: got %b expected %b (paddr=%h t=%0t)", what, got, exp, paddr, $time);
        end
    end
    endtask

    task check_word(input [31:0] got, input [31:0] exp, input [8*48-1:0] what);
    begin
        if (got === exp) passed = passed + 1;
        else begin
            failed = failed + 1;
            $error("FAIL %0s: got %h expected %h (paddr=%h t=%0t)", what, got, exp, paddr, $time);
        end
    end
    endtask

    // Holds in every cycle that is not an access phase.
    task check_quiet(input [8*48-1:0] what);
    begin
        check_word(prdata, 32'h0, what);
        check_bit(pslverr, 1'b0, what);
        check_bit(pready, 1'b1, what);
    end
    endtask

    task apb_write(input [7:0] addr, input [31:0] data, input [3:0] strb, input exp_err);
    begin
        @(negedge pclk);
        psel = 1'b1; penable = 1'b0; pwrite = 1'b1;
        paddr = addr; pwdata = data; pstrb = strb;
        #1 check_quiet("write setup phase quiet");
        @(negedge pclk);
        penable = 1'b1;
        #1;
        check_bit(pready, 1'b1, "write zero wait states");
        check_bit(pslverr, exp_err, "write pslverr");
        check_word(prdata, 32'h0, "write access prdata zero");
        @(posedge pclk);
    end
    endtask

    task apb_read(input [7:0] addr, input [31:0] exp_data, input exp_err);
    begin
        @(negedge pclk);
        psel = 1'b1; penable = 1'b0; pwrite = 1'b0;
        paddr = addr; pwdata = 32'hCAFEBABE; pstrb = 4'h0;
        #1 check_quiet("read setup phase quiet");
        @(negedge pclk);
        penable = 1'b1;
        #1;
        check_bit(pready, 1'b1, "read zero wait states");
        check_bit(pslverr, exp_err, "read pslverr");
        check_word(prdata, exp_data, "read prdata");
        @(posedge pclk);
    end
    endtask

    // Idle cycles with garbage on the bus (alternating write/read controls
    // aimed at REG1) to show nothing happens without psel.
    task apb_idle(input integer n);
        integer k;
    begin
        for (k = 0; k < n; k = k + 1) begin
            @(negedge pclk);
            psel = 1'b0; penable = 1'b0;
            pwrite = k[0]; paddr = 8'h04; pwdata = 32'h00000000; pstrb = 4'hF;
            #1 check_quiet("idle cycle quiet");
        end
    end
    endtask

    task do_reset;
    begin
        @(negedge pclk);
        presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0;
        repeat (3) begin
            @(negedge pclk);
            #1 check_quiet("during reset quiet");
        end
        @(negedge pclk);
        presetn = 1'b1;
    end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";

        // Reset and reset values (back-to-back reads).
        do_reset;
        apb_read(8'h00, 32'h00000000, 1'b0);
        apb_read(8'h04, 32'h00000000, 1'b0);
        apb_read(8'h08, 32'h00000000, 1'b0);
        apb_read(8'h0C, 32'h00000000, 1'b0);
        apb_idle(2);

        // Write every register back to back, then read back to back.
        apb_write(8'h00, 32'hDEADBEEF, 4'hF, 1'b0);
        apb_write(8'h04, 32'h12345678, 4'hF, 1'b0);
        apb_write(8'h08, 32'hA5A55A5A, 4'hF, 1'b0);
        apb_write(8'h0C, 32'hFFFF0000, 4'hF, 1'b0);
        apb_read(8'h00, 32'hDEADBEEF, 1'b0);
        apb_read(8'h04, 32'h12345678, 1'b0);
        apb_read(8'h08, 32'hA5A55A5A, 1'b0);
        apb_read(8'h0C, 32'hFFFF0000, 1'b0);

        // Read immediately after write to the same register.
        apb_write(8'h08, 32'h0BADF00D, 4'hF, 1'b0);
        apb_read(8'h08, 32'h0BADF00D, 1'b0);
        apb_write(8'h08, 32'hA5A55A5A, 4'hF, 1'b0);
        apb_read(8'h08, 32'hA5A55A5A, 1'b0);

        // Idle gaps with garbage on the bus change nothing.
        apb_idle(3);
        apb_read(8'h04, 32'h12345678, 1'b0);
        apb_idle(1);
        apb_read(8'h0C, 32'hFFFF0000, 1'b0);

        // pstrb partial writes and an all-zero strobe.
        apb_write(8'h04, 32'hAABBCCDD, 4'b0101, 1'b0);
        apb_write(8'h08, 32'h11223344, 4'b1010, 1'b0);
        apb_write(8'h0C, 32'h00000000, 4'b0000, 1'b0);
        apb_write(8'h00, 32'h77000000, 4'b1000, 1'b0);
        apb_read(8'h00, 32'h77ADBEEF, 1'b0);
        apb_read(8'h04, 32'h12BB56DD, 1'b0);
        apb_read(8'h08, 32'h11A5335A, 1'b0);
        apb_read(8'h0C, 32'hFFFF0000, 1'b0);
        apb_idle(1);

        // PSLVERR: misaligned writes (one per register index) and reads.
        apb_write(8'h01, 32'h00000000, 4'hF, 1'b1);
        apb_write(8'h06, 32'h00000000, 4'hF, 1'b1);
        apb_write(8'h0B, 32'h00000000, 4'hF, 1'b1);
        apb_write(8'h0F, 32'h00000000, 4'hF, 1'b1);
        apb_read(8'h01, 32'h00000000, 1'b1);
        apb_read(8'h02, 32'h00000000, 1'b1);
        apb_read(8'h07, 32'h00000000, 1'b1);
        apb_read(8'h0E, 32'h00000000, 1'b1);
        apb_idle(1);

        // PSLVERR: out-of-range writes and reads.
        apb_write(8'h10, 32'h00000000, 4'hF, 1'b1);
        apb_write(8'h14, 32'h00000000, 4'hF, 1'b1);
        apb_write(8'h18, 32'h00000000, 4'hF, 1'b1);
        apb_write(8'h1C, 32'h00000000, 4'hF, 1'b1);
        apb_write(8'h80, 32'h00000000, 4'hF, 1'b1);
        apb_write(8'hFC, 32'h00000000, 4'hF, 1'b1);
        apb_write(8'hFF, 32'h00000000, 4'hF, 1'b1);
        apb_read(8'h10, 32'h00000000, 1'b1);
        apb_read(8'h14, 32'h00000000, 1'b1);
        apb_read(8'h18, 32'h00000000, 1'b1);
        apb_read(8'h1C, 32'h00000000, 1'b1);
        apb_read(8'hFC, 32'h00000000, 1'b1);
        apb_read(8'hFF, 32'h00000000, 1'b1);
        apb_idle(2);

        // Unmapped writes changed no register; mapped access still works.
        apb_read(8'h00, 32'h77ADBEEF, 1'b0);
        apb_read(8'h04, 32'h12BB56DD, 1'b0);
        apb_read(8'h08, 32'h11A5335A, 1'b0);
        apb_read(8'h0C, 32'hFFFF0000, 1'b0);

        // Reset again.
        do_reset;
        apb_read(8'h00, 32'h00000000, 1'b0);
        apb_read(8'h04, 32'h00000000, 1'b0);
        apb_read(8'h08, 32'h00000000, 1'b0);
        apb_read(8'h0C, 32'h00000000, 1'b0);
        apb_idle(2);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog: a hung run is a failed run.
    initial begin
        #200000;
        failed = failed + 1;
        $error("FAIL watchdog timeout at t=%0t", $time);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
`default_nettype wire
=== END FILE ===
